<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {request} from '../api'
import {consistency} from '../buildInfo'
import ReaderShell from './ReaderShell.vue'
import ArticleBody from '../reading/ArticleBody.vue'
type About={name:string;intro:string;body:string;motivation:string;notes:string;revision:number}
const defaults=():About=>({name:'Life Journal',intro:'私人的生活档案馆',body:'',motivation:'',notes:'',revision:0})
const saved=ref(defaults()),draft=ref(defaults()),info=ref<any>(null),admin=ref(false),editing=ref(false),busy=ref(false),error=ref(''),message=ref('')
onMounted(async()=>{try{saved.value=await request('/blog/about');draft.value={...saved.value};info.value=await request('/blog/build-info');admin.value=(await request('/admin/status')).is_admin===true}catch(e){error.value=String(e)}})
function cancel(){draft.value={...saved.value};editing.value=false;message.value='已取消未保存修改'}
async function save(){busy.value=true;error.value='';try{const {revision,...values}=draft.value;saved.value=await request('/admin/blog/about',{method:'PUT',body:JSON.stringify({...values,expected_revision:revision})});draft.value={...saved.value};editing.value=false;message.value='网站介绍已保存'}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><ReaderShell><article class="about-page"><p class="blog-kicker">OUR PRIVATE ARCHIVE</p><h1>关于本站</h1><p v-if="error" role="alert">{{error}}</p><p role="status">{{message}}</p><template v-if="!editing"><h2>{{saved.name}}</h2><p class="about-intro">{{saved.intro}}</p><ArticleBody v-if="saved.body" :source="saved.body" namespace="about"/><p v-else>这里收藏生活中的故事与值得记住的片刻。</p><section v-if="saved.motivation"><h2>建站初衷</h2><p class="free-text">{{saved.motivation}}</p></section><p v-if="saved.notes" class="free-text">{{saved.notes}}</p><button v-if="admin" class="quiet" @click="editing=true">编辑网站介绍</button></template><form v-else @submit.prevent="save"><fieldset :disabled="busy"><legend>管理员编辑网站介绍</legend><label>网站名称<input v-model="draft.name" maxlength="100"/></label><label>简介<input v-model="draft.intro" maxlength="1000"/></label><label>关于本站正文（Markdown）<textarea v-model="draft.body" rows="10" maxlength="20000"/></label><label>建站初衷<textarea v-model="draft.motivation" maxlength="2000"/></label><label>补充说明<textarea v-model="draft.notes" maxlength="2000"/></label><details><summary>介绍预览</summary><ArticleBody :source="draft.body" namespace="about-preview"/></details><div class="actions"><button>保存网站介绍</button><button type="button" class="quiet" @click="cancel">取消介绍修改</button></div></fieldset></form><section v-if="info" class="build-notes"><h2>当前版本</h2><p>v{{info.version}} · {{info.short_revision||'构建提交未记录'}}</p><p>{{info.revision_verified?'构建时 Git 提交已核对':info.source_kind==='user-provided-zip'?'ZIP 声明 SHA，未经 Git 验证':'本地开发 / 未验证构建'}}</p><p v-if="info.built_at">构建时间：{{info.built_at}}（UTC）</p><details v-if="admin"><summary>管理员构建诊断</summary><p>完整 Commit：{{info.revision||'未记录'}}</p><p>{{consistency(info)}}</p><p>此处仅比较构建阶段记录的来源标识，不验证镜像内容、签名或供应链完整性；ZIP 声明不会因此变成已验证的 Git 来源。</p></details><details v-if="info.changelog?.length"><summary>最近更新记录</summary><section v-for="entry in info.changelog" :key="entry.title"><h3>{{entry.title}}</h3><ArticleBody :source="entry.body" :namespace="'changelog-'+entry.title.replace(/\W/g,'')"/></section></details></section><RouterLink to="/">返回私人首页</RouterLink></article></ReaderShell></template>
<style scoped>.about-page{max-width:760px;margin:12px auto 50px;min-width:0}.about-page h1{font-size:clamp(32px,5vw,54px);font-weight:500;margin:20px 0 40px}.about-intro{font-size:20px;line-height:1.7}.free-text{white-space:pre-wrap;line-height:1.8;overflow-wrap:anywhere}.build-notes{border-top:1px solid var(--line);margin-top:40px;padding:24px 0;color:var(--muted)}.build-notes h2{font-size:18px}details{padding:12px 0}summary{cursor:pointer;min-height:40px}details[open]>summary{font-weight:700}.about-page :deep(.blog-prose){margin-block:24px}.about-page input,.about-page textarea{color:var(--ink);background:var(--surface);border-color:var(--line)}fieldset{min-width:0;border:0;padding:0}.build-notes p{overflow-wrap:anywhere}@media(max-width:600px){.about-page h1{margin-bottom:24px}.about-page{margin-top:0}}</style>
